    16	function stripSpacesFromAmount(amount: string): string {
    17	    return amount.replace(/\s+/g, '');
    18	}
    19	
    20	function replaceCommasWithPeriod(amount: string): string {
    21	    return amount.replace(/,+/g, '.');
    22	}
    23	
    24	/**
    25	 * Strip decimals from the amount
    26	 */
    27	function stripDecimalsFromAmount(amount: string): string {
    28	    return amount.replace(/\.\d*$/, '');
    29	}
    30	
    31	/**
    32	 * Adds a leading zero to the amount if user entered just the decimal separator
    33	 *
    34	 * @param amount - Changed amount from user input
    35	 */
    36	function addLeadingZero(amount: string): string {
    37	    return amount.startsWith('.') ? `0${amount}` : amount;
    38	}
    39	
    40	/**
    41	 * Check if amount is a decimal up to 3 digits
    42	 */
    43	function validateAmount(amount: string, decimals: number, amountMaxLength: number = CONST.IOU.AMOUNT_MAX_LENGTH): boolean {
    44	    const regexString =
    45	        decimals === 0
    46	            ? `^\\d{1,${amountMaxLength}}$` // Don't allow decimal point if decimals === 0
    47	            : `^\\d{1,${amountMaxLength}}(\\.\\d{0,${decimals}})?$`; // Allow the decimal point and the desired number of digits after the point
    48	    const decimalNumberRegex = new RegExp(regexString, 'i');
    49	    return amount === '' || decimalNumberRegex.test(amount);
    50	}
    51	
    52	/**
    53	 * Check if percentage is between 0 and 100
    54	 */
    55	function validatePercentage(amount: string): boolean {
    56	    const regexString = '^(100|[0-9]{1,2})$';
    57	    const percentageRegex = new RegExp(regexString, 'i');
    58	    return amount === '' || percentageRegex.test(amount);
    59	}
    60	
    61	/**
    62	 * Replaces each character by calling `convertFn`. If `convertFn` throws an error, then
    63	 * the original character will be preserved.
    64	 */
    65	function replaceAllDigits(text: string, convertFn: (char: string) => string): string {
    66	    return text
    67	        .split('')
    68	        .map((char) => {
    69	            try {
    70	                return convertFn(char);
    71	            } catch {
    72	                return char;
    73	            }
    74	        })
    75	        .join('');
    76	}
